# ==============================================================================
# Script: 09_Plot_Figs5_6_S3_Spatial_Ensemble.R
# Title: Master Spatial Ensemble Visualization Suite (Figures 5, 6, and S3)
# Description: Loads the 10-fold spatial bootstrap ensemble outputs generated by
#              05_Spatial_Ensemble_MLP_SPAT.R and produces:
#                - Figure 5: Basin-wide area-weighted TTI trajectory (1955-2020)
#                - Figure 6: 6-panel spatio-temporal TTI reconstruction (1970, 1995, 2020)
#                - Figure S3: 6-panel ensemble mean & pixel-wise uncertainty (SD)
# Reference: Stips et al. (2026) - Environmental Modelling & Software
# License: GPL-3.0
# ==============================================================================

library(ggplot2)
library(dplyr)
library(scales)
library(ggpubr)
library(patchwork)

# --- 1. DIRECTORY SETUP & DATA LOADING ---
in_dir  <- ifelse(dir.exists("./Output"), "./Output", "./")
fig_dir <- "./Figures"
if (!dir.exists(fig_dir)) dir.create(fig_dir, recursive = TRUE)

ts_file  <- file.path(in_dir, "Ensemble_TimeSeries_MLP_SPAT.rds")
map_file <- file.path(in_dir, "Ensemble_Map_Data_MLP_SPAT.rds")

if (!file.exists(ts_file) || !file.exists(map_file)) {
  stop("Ensemble output files not found in: ", in_dir,
       "\nPlease run 05_Spatial_Ensemble_MLP_SPAT.R first.")
}

ensemble_ts_data  <- readRDS(ts_file)
ensemble_map_data <- readRDS(map_file)

# ==============================================================================
# 2. GENERATE FIGURE 5: BASIN-WIDE TEMPORAL EVOLUTION OF MEAN TTI (1955-2020)
# ==============================================================================
if ("Pred_TTI_Mean" %in% colnames(ensemble_ts_data)) {
  plot_data_fig5 <- ensemble_ts_data %>%
    mutate(
      True_TTI = True_TTI_Mean,
      ANN_Mean = Pred_TTI_Mean,
      Lower    = Pred_TTI_Mean - Pred_TTI_CI,
      Upper    = Pred_TTI_Mean + Pred_TTI_CI
    )
} else {
  plot_data_fig5 <- ensemble_ts_data %>%
    mutate(
      Z_ANN  = atanh(pmin(pmax(ANN_Mean_TTI, -0.999), 0.999)),
      Z_True = atanh(pmin(pmax(True_Mean_TTI, -0.999), 0.999))
    ) %>%
    group_by(Year) %>%
    summarize(
      True_TTI = tanh(mean(Z_True)),
      Mean_Z   = mean(Z_ANN),
      CI_Z     = 1.96 * (sd(Z_ANN) / sqrt(n())),
      ANN_Mean = tanh(Mean_Z),
      Lower    = tanh(Mean_Z - CI_Z),
      Upper    = tanh(Mean_Z + CI_Z),
      .groups  = "drop"
    )
}

df_ts_true <- data.frame(
  Year     = plot_data_fig5$Year,
  Model    = "Ecosystem Model (True TTI)",
  Mean_TTI = plot_data_fig5$True_TTI,
  Lower    = NA,
  Upper    = NA
)

df_ts_ann <- data.frame(
  Year     = plot_data_fig5$Year,
  Model    = "MLP_SPAT Ensemble (Predicted TTI)",
  Mean_TTI = plot_data_fig5$ANN_Mean,
  Lower    = plot_data_fig5$Lower,
  Upper    = plot_data_fig5$Upper
)

final_fig5_df <- rbind(df_ts_true, df_ts_ann)
final_fig5_df$Model <- factor(
  final_fig5_df$Model, 
  levels = c("Ecosystem Model (True TTI)", "MLP_SPAT Ensemble (Predicted TTI)")
)

p_fig5 <- ggplot(final_fig5_df, aes(x = Year, y = Mean_TTI, color = Model, shape = Model, size = Model)) +
  geom_hline(yintercept = 0.71, color = "grey50", linetype = "dashed", linewidth = 1) +
  geom_errorbar(aes(ymin = Lower, ymax = Upper), width = 1.8, linewidth = 0.9, 
                position = position_dodge(width = 0.7), na.rm = TRUE, show.legend = FALSE) +
  geom_line(linewidth = 1.2, position = position_dodge(width = 0.5)) +
  geom_point(fill = "white", stroke = 1.2, position = position_dodge(width = 0.5)) +
  scale_color_manual(values = c("Ecosystem Model (True TTI)"        = "black", 
                                "MLP_SPAT Ensemble (Predicted TTI)" = "#E69F00")) +
  scale_shape_manual(values = c(16, 21)) +
  scale_size_manual(values = c("Ecosystem Model (True TTI)"        = 3.0, 
                               "MLP_SPAT Ensemble (Predicted TTI)" = 1.2)) +
  scale_x_continuous(breaks = seq(1955, 2020, by = 5), expand = c(0.02, 0.02)) +
  labs(
    title    = "Temporal Evolution of Mean Trophic Transfer Index",
    subtitle = "Basin-wide reconstruction using a 10-fold spatial bootstrap ensemble",
    x        = "Assessment Year (Pentad Center)",
    y        = "Area-Weighted Mean TTI",
    color    = NULL, shape = NULL, size = NULL
  ) +
  theme_pubr(base_size = 14) +
  theme(
    plot.title        = element_text(face = "bold", hjust = 0.5, size = 16),
    plot.subtitle     = element_text(hjust = 0.5, size = 12, color = "grey30", margin = margin(b = 15)),
    legend.position   = "bottom",
    legend.text       = element_text(size = 12, face = "bold"),
    legend.background = element_rect(fill = NA, color = NA),
    legend.margin     = margin(t = 5),
    panel.grid.major  = element_line(color = "grey85"),
    axis.title        = element_text(face = "bold", size = 14),
    axis.text         = element_text(color = "black", size = 12)
  )

fig5_file <- file.path(fig_dir, "Figure5_Temporal_TTI_Spatial_Ensemble.png")
ggsave(fig5_file, plot = p_fig5, width = 8.5, height = 5.5, dpi = 500, bg = "white")
message("Figure 5 successfully saved to: ", fig5_file)

# ==============================================================================
# 3. GENERATE FIGURE 6: SPATIO-TEMPORAL TTI RECONSTRUCTION (1970, 1995, 2020)
# ==============================================================================
target_years <- c(1970, 1995, 2020)

# Colorblind-safe diverging palette centered on GES threshold (0.71)
tti_colors <- c("#d73027", "#f46d43", "#fdae61", "#ffffbf", "#abd9e9", "#74add1", "#4575b4")
tti_values <- scales::rescale(c(0.4, 0.55, 0.68, 0.71, 0.75, 0.85, 1.0))

df_map_true <- data.frame(
  Longitude = ensemble_map_data$Longitude,
  Latitude  = ensemble_map_data$Latitude,
  Year      = paste("Pentad Center:", ensemble_map_data$Year),
  Type      = "Ecosystem Model\n(True TTI)",
  Value     = ensemble_map_data$True_TTI
)

df_map_ann <- data.frame(
  Longitude = ensemble_map_data$Longitude,
  Latitude  = ensemble_map_data$Latitude,
  Year      = paste("Pentad Center:", ensemble_map_data$Year),
  Type      = "MLP_SPAT Ensemble\n(Predicted Mean TTI)",
  Value     = ensemble_map_data$Ensemble_Mean_TTI
)

panel_collection <- rbind(df_map_true, df_map_ann)
panel_collection$Type <- factor(
  panel_collection$Type, 
  levels = c("Ecosystem Model\n(True TTI)", "MLP_SPAT Ensemble\n(Predicted Mean TTI)")
)
panel_collection$Year <- factor(
  panel_collection$Year, 
  levels = paste("Pentad Center:", target_years)
)

p_fig6 <- ggplot(panel_collection, aes(x = Longitude, y = Latitude)) +
  geom_raster(aes(fill = Value)) +
  scale_fill_gradientn(
    colors = tti_colors,
    values = tti_values,
    limits = c(0.4, 1.0),
    oob    = scales::squish,
    name   = "TTI Value:",
    guide  = guide_colorbar(title.position = "top", title.hjust = 0.5) 
  ) +
  geom_contour(aes(z = Value), breaks = 0.71, colour = "black", linewidth = 0.6, alpha = 0.8) +
  coord_fixed(ratio = 1.7) +
  scale_x_continuous(
    labels = function(x) paste0(x, "\u00B0E"), 
    breaks = seq(10, 30, by = 10), 
    limits = c(9.0, 30.5), 
    expand = c(0, 0)
  ) +
  scale_y_continuous(
    labels = function(y) paste0(y, "\u00B0N"), 
    breaks = seq(54, 66, by = 4), 
    limits = c(53.5, 66.5), 
    expand = c(0, 0)
  ) +
  facet_grid(Year ~ Type) +
  labs(
    title = "Spatio-Temporal Reconstruction of Baltic Sea Trophic Status",
    x     = "Longitude",
    y     = "Latitude"
  ) +
  theme_pubr(base_size = 14) +
  theme(
    plot.title       = element_text(face = "bold", hjust = 0.5, size = 16, margin = margin(b = 15)),
    strip.text       = element_text(face = "bold", size = 13), 
    strip.background = element_rect(fill = "grey95", color = "black", linewidth = 0.8),
    panel.border     = element_rect(colour = "black", fill = NA, linewidth = 0.8),
    panel.spacing    = unit(1, "lines"), 
    legend.position  = "bottom",
    legend.title     = element_text(face = "bold", size = 14),
    legend.text      = element_text(size = 12),
    legend.key.width = unit(2.0, "cm"), 
    legend.margin    = margin(t = 10),
    axis.text        = element_text(color = "black", size = 11),
    axis.title       = element_text(face = "bold", size = 13)
  )

fig6_file <- file.path(fig_dir, "Figure6_Spatio_Temporal_TTI_Ensemble_Grid.png")
ggsave(fig6_file, plot = p_fig6, width = 7.48, height = 9.5, dpi = 500, bg = "white")
message("Figure 6 successfully saved to: ", fig6_file)

# ==============================================================================
# 4. GENERATE SUPPLEMENTARY FIGURE S3: ENSEMBLE MEAN & UNCERTAINTY (SD) MAPS
# ==============================================================================
fig_s3_data <- ensemble_map_data
fig_s3_data$Year <- factor(
  paste("Pentad Center:", fig_s3_data$Year), 
  levels = paste("Pentad Center:", target_years)
)

p_s3_mean <- ggplot(fig_s3_data, aes(x = Longitude, y = Latitude)) +
  geom_raster(aes(fill = Ensemble_Mean_TTI)) +
  scale_fill_gradientn(
    colors = tti_colors,
    values = tti_values,
    limits = c(0.4, 1.0),
    oob    = scales::squish,
    name   = "Mean TTI:",
    guide  = guide_colorbar(title.position = "top", title.hjust = 0.5)
  ) +
  geom_contour(aes(z = Ensemble_Mean_TTI), breaks = 0.71, colour = "black", linewidth = 0.6, alpha = 0.8) +
  coord_fixed(ratio = 1.7) +
  scale_x_continuous(
    labels = function(x) paste0(x, "\u00B0E"), 
    breaks = seq(10, 30, by = 10), 
    limits = c(9.0, 30.5), 
    expand = c(0, 0)
  ) +
  scale_y_continuous(
    labels = function(y) paste0(y, "\u00B0N"), 
    breaks = seq(54, 66, by = 4), 
    limits = c(53.5, 66.5), 
    expand = c(0, 0)
  ) +
  facet_grid(Year ~ .) +
  labs(title = "A: Predicted Mean TTI", x = "Longitude", y = "Latitude") +
  theme_pubr(base_size = 14) +
  theme(
    plot.title       = element_text(face = "bold", hjust = 0.5, size = 14),
    strip.text       = element_text(face = "bold", size = 12),
    strip.background = element_rect(fill = "grey95", color = "black"),
    panel.border     = element_rect(colour = "black", fill = NA, linewidth = 0.8),
    legend.position  = "bottom",
    legend.key.width = unit(1.5, "cm")
  )

p_s3_sd <- ggplot(fig_s3_data, aes(x = Longitude, y = Latitude)) +
  geom_raster(aes(fill = Ensemble_SD_TTI)) +
  scale_fill_viridis_c(
    option = "plasma", 
    name   = "TTI SD (Uncertainty):",
    limits = c(0, 0.10), 
    breaks = c(0, 0.05, 0.10),
    labels = c("0.00", "0.05", ">0.10"),
    oob    = scales::squish,
    guide  = guide_colorbar(title.position = "top", title.hjust = 0.5)
  ) +
  coord_fixed(ratio = 1.7) +
  scale_x_continuous(
    labels = function(x) paste0(x, "\u00B0E"), 
    breaks = seq(10, 30, by = 10), 
    limits = c(9.0, 30.5), 
    expand = c(0, 0)
  ) +
  scale_y_continuous(
    labels = function(y) paste0(y, "\u00B0N"), 
    breaks = seq(54, 66, by = 4), 
    limits = c(53.5, 66.5), 
    expand = c(0, 0) 
  ) +
  facet_grid(Year ~ .) +
  labs(title = "B: Spatial Bootstrap Uncertainty", x = "Longitude", y = NULL) +
  theme_pubr(base_size = 14) +
  theme(
    plot.title       = element_text(face = "bold", hjust = 0.5, size = 14),
    strip.text       = element_blank(), 
    panel.border     = element_rect(colour = "black", fill = NA, linewidth = 0.8),
    legend.position  = "bottom",
    legend.key.width = unit(1.5, "cm"),
    axis.text.y      = element_blank(),
    axis.ticks.y     = element_blank()
  )

p_fig_s3 <- p_s3_mean + p_s3_sd + 
  plot_annotation(
    title = "MLP_SPAT Spatial Bootstrap Ensemble (Means and Standard Deviations)",
    theme = theme(plot.title = element_text(face = "bold", hjust = 0.5, size = 16, margin = margin(b = 15)))
  )

figs3_file <- file.path(fig_dir, "Figure_S3_Ensemble_Uncertainty_Maps.png")
ggsave(figs3_file, plot = p_fig_s3, width = 8.5, height = 9.5, dpi = 500, bg = "white")
message("Supplementary Figure S3 successfully saved to: ", figs3_file)

